import{_ as e,o as i,c as a,a3 as t}from"./chunks/framework.DAK02U1-.js";const c=JSON.parse('{"title":"Releasing","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Releasing | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/dev/releasing"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/dev/releasing"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/dev/releasing"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/dev/releasing"}]]},"headers":[],"relativePath":"xclang/dev/releasing.md","filePath":"en/xclang/dev/releasing.md","lastUpdated":1791308802000}'),n={name:"xclang/dev/releasing.md"};function l(h,s,r,o,p,d){return i(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="releasing" tabindex="-1">Releasing <a class="header-anchor" href="#releasing" aria-label="Permalink to &quot;Releasing&quot;">​</a></h1><p>How a release <code>&lt;llvm version&gt;.&lt;revision&gt;</code> is cut. The step list for maintainers is the release skill in <a href="https://github.com/clice-io/xclang/blob/main/.claude/skills/release/SKILL.md" target="_blank" rel="noreferrer">.claude/skills/release</a>; this page is the same process, for people. What the pipeline does is in the <a href="./release-build">build pipeline</a>.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li><strong>Nothing published is replaced.</strong> A rebuild, even of the same commit, is the next revision; the <code>release</code> stage refuses a version that exists.</li><li><strong>Builds run on CI</strong>, on GitHub-hosted runners, from a branch <code>exp/&lt;version&gt;</code>, not from <code>main</code>.</li><li><strong>A pending release is not mixed with pipeline changes</strong>: the release goes out with the pipeline that has been tested.</li></ul><h2 id="full-rebuild-or-repack" tabindex="-1">Full Rebuild or Repack <a class="header-anchor" href="#full-rebuild-or-repack" aria-label="Permalink to &quot;Full Rebuild or Repack&quot;">​</a></h2><p>A release whose changes are all in what the <code>package</code> stage reads from the checkout is a <strong>repack</strong>: the config files (<code>config/</code>), the CMake package (<code>packages/cmake</code>), the Bazel module (<code>packages/bazel</code>, which the archives do not hold), the <code>xclang</code> command (<code>cli/</code>), the license notices and <code>scripts/package.ts</code>. It reuses the compiler, runtimes, libclang and profile of the run that built the previous release, the same bytes, and takes about half an hour instead of three hours. Anything built into those, such as a patch, a pinned source, the runtimes, the CMake caches or the training, needs a full rebuild. A fix of the conda packages alone is no release, but the next conda build number of the same one.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><strong>Bootstrap.</strong> <code>scripts/common.ts</code> pins the release that builds this one (<code>bootstrap-linux</code>, <code>bootstrap-macos</code>, with their sha256 from that release&#39;s <code>SHA256SUMS</code>). Move it to the previous release when that one has what the build needs.</li><li><strong>Full run with a draft</strong>, about three hours:<div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clice-io/xclang</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ref</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exp/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stages=runtimes,instrumented,train,toolchain,asan,package,test,bazel,cmake,msvc,macos,release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revision=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div>A failed stage is run again with <code>reuse-run</code> and only the stages still to do. A repack, in about half an hour, skips the bootstrap step:<div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clice-io/xclang</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ref</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exp/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stages=package,test,bazel,cmake,msvc,macos,release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reuse-run=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">full</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ru</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> profile-run=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">full</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ru</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repack-of=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">previous</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revision=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><code>&lt;full run&gt;</code> is the run that built the compiler. Its toolchain and runtimes artifacts last 14 days, its profile 30; after that, only a full rebuild can make a release. With <code>repack-of</code>, the <code>repack</code> job checks each host&#39;s archives against that release&#39;s, file by file (<code>tests/repack.ts</code>): only the packaging&#39;s files may differ.</li><li><strong>Check the draft</strong>: 17 assets, the test, bazel, cmake, msvc and macos jobs green (and repack&#39;s, for a repack), sizes against the previous release.</li><li><strong>Notes</strong>: what it was built by, then what changed for users, from CHANGELOG.md&#39;s Unreleased section. A repack&#39;s say that the compiler and runtimes are the previous release&#39;s, the same bytes.</li><li><strong>Publish</strong>, which creates the tag. That starts bazel.yml, which tests the tag&#39;s module with the published archives and publishes it to bazel.clice.io, and cmake.yml, which builds tests/cmake from the tag as a user&#39;s FetchContent does.</li><li><strong>conda</strong>: <code>conda.yml</code> with the tag makes, tests and publishes the conda packages; a packaging fix of the same release is the next build number.</li><li><strong>After publishing</strong>, one commit on <code>main</code>, <code>readme: &lt;version&gt;</code>: the module&#39;s <code>versions.bzl</code> from the release&#39;s <code>SHA256SUMS</code>, the version in the module files, the README, the docs and examples/ (<code>grep -rn &lt;previous version&gt;</code> finds them), the runs table of <a href="./testing">testing</a>, and CHANGELOG.md&#39;s Unreleased becomes the release&#39;s section.</li><li><strong>examples.yml</strong>, by hand, once conda.clice.io and bazel.clice.io have the release: the docs&#39; commands against it on every host.</li><li><strong>bench.yml</strong> with the release run&#39;s artifacts, when performance matters for the notes or the docs.</li></ol>`,8)])])}const g=e(n,[["render",l]]);export{c as __pageData,g as default};
